import { PlayerData, RequestType } from '@game-studio/server-comms';
import { OverlaysEventEmitter } from '@game-studio/overlays';

import { inversifyContainer } from '../inversify/container';
import { eventEmitter } from '../services/event-emitter';
import { BalanceModel } from './balance';
import { device } from '../services/device';
import { demoState } from './demo-model';
import { gameConfig } from './config-model';

export class User {
    public static get Instance(): User { return this._instance || (this._instance = new User()); }
    private static _instance: User;

    public hideBalance: boolean = false;

    private _userId: number|string = 0;
    private _crossCheck: number = 0;
    private _clientTypeId: number = -1;

    private _username: string = '';
    private _previousStake: number = 0;
    private _totalBalance = new BalanceModel();
    private _walletBalance = new BalanceModel();
    private _freePlayBalance: number = 0;

    private constructor() { }

    public get userId(): number | string {
        return this._userId;
    }

    public get crossCheck(): number {
        return this._crossCheck;
    }

    public get clientTypeId(): number {
        return this._clientTypeId;
    }

    public get username(): string {
        return this._username;
    }

    public get previousStake(): number {
        return this._previousStake;
    }

    public get totalBalance(): BalanceModel {
        return this._totalBalance;
    }

    /** @deprecated use visibleBalance instead, for wallet.setBalance use user.setWalletBalance */
    public get wallet(): typeof this.visibleBalance {
        return this.visibleBalance;
    }

    /** returns the balance as it should be shown to the user */
    public get visibleBalance(): { startBalance: number; endBalance: number } {
        if (gameConfig.coreFeatures.useWalletBalance) {
            return {
                startBalance: Math.min(this._totalBalance.startBalance, this._walletBalance.startBalance),
                endBalance: Math.min(this._totalBalance.endBalance, this._walletBalance.endBalance)
            };
        } else {
            return {
                startBalance: this._totalBalance.startBalance,
                endBalance: this._totalBalance.endBalance
            };
        }
    }

    public get freePlayBalance(): number {
        return this._freePlayBalance;
    }

    public updateFreePlayBalance(newBalance: number, requestType: RequestType | 'Error'): void {
        if (gameConfig.supportsFreeplays && newBalance !== 0) {
            if (requestType === 'Begin' && (newBalance >= this._freePlayBalance)) {
                if (!inversifyContainer.cabinet.inFreePlay) {
                    eventEmitter.emit('GLOBAL_FREE_PLAY_EARNED', newBalance);
                } else {
                    OverlaysEventEmitter.emit('showToast', '', inversifyContainer.strings.freePlay.awarded);
                }
            }
        }
        this._freePlayBalance = gameConfig.supportsFreeplays ? newBalance : 0;
    }

    public setData(playerData: PlayerData, requestType: 'FromBingo', gameComplete?: boolean): void;
    public setData(playerData: PlayerData, requestType: RequestType, gameComplete?: boolean, sessionStatus?: { InPlaySessionBalance?: number; TrueSessionBalance?: number; }): void;
    public setData(playerData: PlayerData, requestType: RequestType | 'FromBingo', gameComplete: boolean = false, sessionStatus?: { InPlaySessionBalance?: number; TrueSessionBalance?: number; }): void {
        this._username = playerData.Username;
        this._previousStake = playerData.PreviousStake;

        // Demo begin/continue requests send balance data as 0 so ignoring those
        if (demoState.isDemoMode && (requestType === 'Begin' || requestType === 'Continue')) { return; }

        this._totalBalance.setData(playerData.StartBalance, playerData.EndBalance);

        if (requestType !== 'FromBingo') {
            const walletStartBalance = sessionStatus?.InPlaySessionBalance ?? playerData.StartBalance;
            const walletEndBalance = sessionStatus?.TrueSessionBalance ?? playerData.EndBalance;
            this._walletBalance.setData(walletStartBalance, walletEndBalance);
        }

        // Update freeplay balance on begin and resume requests, and on continue if it's the last spin.
        if ((requestType !== 'Continue' || requestType === 'Continue' && gameComplete) && requestType !== 'FromBingo') {
            this.updateFreePlayBalance(playerData.FreePlayBalance, requestType);
        }
    }

    public setWalletData(startBalance: number, endBalance: number): void {
        this._walletBalance.setData(startBalance, endBalance);
        this.hideBalance = false;
    }

    public setCredentials(id: number | string, cc: number): void {
        this._userId = id;
        this._crossCheck = cc;
        this._clientTypeId = Number(device.typeCode.split('.').join(''));
    }
}

export const userModel = User.Instance;
